//! Builds five models into one crate, each through the full simjig-build pipeline:
//! - `counter` (tests/duts/counter, WIDTH=12): the end-to-end vtable check;
//! - `timing_dut` with `--timing`: C++20 coroutines;
//! - `counter_fst`: the counter again, with `--trace-fst` (lz4 and zlib);
//! - `inv` and `flop`: two models with different prefixes in one binary.
//!
//! All five share one libverilated. The emitter here is a stand-in for the real code
//! generator: it binds every top-level port and declares the vtable symbol in Rust.

use simjig_build::svtypes::ir::{Design, Direction};
use simjig_build::{Dut, DutConfig, Emitted, Error};

fn main() -> Result<(), Error> {
    let dut = |name: &str, dir: &str| {
        Dut::new(name)
            .sources([format!("duts/{dir}/{dir}.sv")])
            .top(dir)
            .emitter(emit)
    };
    dut("counter", "counter").param("WIDTH", 12).build()?;
    dut("timing_dut", "timing_dut").timing(true).build()?;
    dut("counter_fst", "counter").trace_fst(true).build()?;
    dut("inv", "inv").build()?;
    dut("flop", "flop").build()?;
    Ok(())
}

/// Binds every port of the top module and exports the vtable; for `--trace-fst` models
/// also exports `<name>_fst_dump(path)`, which writes a short FST trace.
fn emit(design: &Design, config: &DutConfig) -> Result<Emitted, Error> {
    let prefix = config.prefix();
    let top = design.top_module();
    let mut binds = String::new();
    for p in &top.ports {
        let width = design.ty(p.ty).width.expect("packed port");
        let (dir, access) = match p.dir {
            Direction::Input => ("SIMJIG_DIR_IN", "SIMJIG_ACCESS_READ | SIMJIG_ACCESS_WRITE"),
            Direction::Output => ("SIMJIG_DIR_OUT", "SIMJIG_ACCESS_READ"),
            Direction::Inout => ("SIMJIG_DIR_INOUT", "SIMJIG_ACCESS_READ | SIMJIG_ACCESS_WRITE"),
        };
        let member = p.cpp_member.as_deref().unwrap_or(&p.name);
        binds += &format!(
            "        SIMJIG_SIGNAL(t, m.{member}, \"{}.{}\", {width}, {dir}, {access});\n",
            top.name, p.name
        );
    }
    let name = &config.name;
    let mut shim = format!(
        "#include \"{prefix}.h\"\n#include \"simjig_model.h\"\n\n\
         namespace {{\nstruct Traits {{\n    using Model = {prefix};\n\
         \x20   static constexpr const char* kPrefix = \"{prefix}\";\n\
         \x20   static constexpr uint64_t kIrHash = 0;\n\
         \x20   static constexpr bool kTiming = {};\n\
         \x20   static void bind({prefix}& m, simjig::SignalTable& t) {{\n{binds}    }}\n}};\n}}\n\n\
         SIMJIG_EXPORT_VTABLE({prefix}, Traits)\n",
        config.timing
    );
    let mut rust = format!(
        "// @generated by the fixture emitter.\n\
         pub const PREFIX: &str = {prefix:?};\n\
         unsafe extern \"C\" {{\n\
         \x20   #[link_name = \"simjig_vtable_{prefix}\"]\n\
         \x20   pub safe fn vtable() -> *const super::Vtable;\n"
    );
    if config.trace_fst {
        shim += &format!(
            "\n#include \"verilated_fst_c.h\"\n\
             extern \"C\" int {name}_fst_dump(const char* path) {{\n\
             \x20   VerilatedContext ctx;\n    ctx.traceEverOn(true);\n\
             \x20   {prefix} m{{&ctx, \"top\"}};\n    VerilatedFstC tfp;\n\
             \x20   m.trace(&tfp, 99);\n    tfp.open(path);\n\
             \x20   for (int i = 0; i < 8; ++i) {{\n\
             \x20       m.clk = i & 1; m.rst = i < 2; m.en = 1; m.eval();\n\
             \x20       tfp.dump(ctx.time()); ctx.timeInc(1);\n    }}\n\
             \x20   tfp.close();\n    m.final();\n    return 0;\n}}\n"
        );
        rust += &format!(
            "    #[link_name = \"{name}_fst_dump\"]\n\
             \x20   pub unsafe fn fst_dump(path: *const core::ffi::c_char) -> i32;\n"
        );
    }
    rust += "}\n";
    Ok(Emitted {
        rust: Some(rust),
        shim_cpp: Some(shim),
        ..Emitted::default()
    })
}
